@cli.command()
@click.argument("dataset_path", type=click.Path(exists=True))
@click.argument("output_path", type=click.Path())
def build_from_dataset(dataset_path, output_path):
    """Build a dataset collection from a single dataset."""
    logger = get_logger(__name__, logging.INFO)

    dataset = Dataset(dataset_path)
    dataset_collection = DatasetCollection(
        dataset_collection_path=Path(),
        dataset_collection_builder=DatasetCollectionBuilder(logger),
    )
    dataset_collection.add_dataset(dataset)
    dataset_collection.build()
    logger.info(f"Saving dataset collection to {output_path}")
    dataset_collection.save(output_path)


@cli.command()
@click.argument("dataset_collection_path", type=click.Path(exists=True))
@click.argument("output_path", type=click.Path())
@click.option("--limit", type=int)
def split_train_test(dataset_collection_path, output_path, limit):
    """Split a dataset collection into train and test datasets."""
    logger = get_logger(__name__, logging.INFO)

    dataset_collection = DatasetCollection(
        dataset_collection_path,
        dataset_collection_builder=DatasetCollectionBuilder(logger),
    )
    dataset_collection.build()

    train_dataset = dataset_collection.train_dataset
    test_dataset = dataset_collection.test_dataset
    if limit:
        train_dataset = train_dataset[:limit]
        test_dataset = test_dataset[:limit]

    logger.info(f"Saving train dataset to {output_path}")
    train_dataset.save(output_path)

